// Only aggregated counts leave this sub-workflow. Personal data must NOT reach the agent.
const payload = $input.first()?.json ?? {};
const orders = Array.isArray(payload.data) ? payload.data : [];
const statusCounts = Object.create(null);
const sourceCounts = Object.create(null);
let sum = 0, amounts = 0;
for (const o of orders) {
  const s = String(o.status_id ?? 'unknown');
  const source = String(o.source_id ?? 'unknown');
  statusCounts[s] = (statusCounts[s] || 0) + 1;
  sourceCounts[source] = (sourceCounts[source] || 0) + 1;
  if (o.grand_total !== undefined && o.grand_total !== null && Number.isFinite(Number(o.grand_total))) {
    sum += Number(o.grand_total);
    amounts++;
  }
}
return [{json:{
  result_type: "KeyCRM_first_page_only",
  sample_orders: orders.length,
  max_requested: 50,
  page: 1,
  status_id_counts: statusCounts,
  source_id_counts: sourceCounts,
  sample_grand_total: amounts ? Math.round(sum * 100)/100 : null,
  records_with_grand_total: amounts,
  data_completeness: "INCOMPLETE: only page 1, no date filter; do not report totals or conversion rates for a month/all orders.",
  status_mapping_required: true,
  source_mapping_required: true,
  currency_not_verified: true,
  raw_client_data_sent_to_agent: false
}}];
